head.script:
///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★
스크립트 수작업 유의사항

*/

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 로그인 세션 확인 후 사용자 정보를 세팅하고 화면 초기화(gform_onload)를 수행한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function() {
    try {
        if(!$c.session.isLogin()){
            await $c.session.setUserInfo();
        }else{

        }

        scwin.clickId;
        scwin.gIsurCd;
        scwin.clickSubmitYn;

        scwin.gform_onload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30304.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 처리(현재 처리 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description 기간선택 콤보 변경 이벤트 — 선택한 기간값으로 시작일·종료일을 세팅한다.
 * @returns {void}
 * @hidden N
 * @example scwin.cmb_PeriodTp_onselchange();
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description 회사코드 입력 blur 이벤트 — 회사코드가 비어 있으면 회사명을 초기화한다(후행 동일명 정의로 대체됨).
 * @returns {void}
 * @hidden N
 * @example scwin.txb_isur_cd_onblur();
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description 회사코드(명) 돋보기 버튼 클릭 이벤트 — 발행회사검색창 팝업을 호출한다.
 * @returns {void}
 * @hidden N
 * @example scwin.img_com_srch_onclick();
 */
scwin.img_com_srch_onclick = function() {
    try {
        // 발행회사검색창
        $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 등록 버튼 클릭 이벤트 — IR자료실 등록 팝업을 호출한 뒤 목록을 재조회한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.btn_Input_onclick();
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.clickId = "input";
        const options = {
            id: "ULDSTF30305",
            title: "IR자료실 등록",
            type: "browserPopup",
            width: "725px",
            height: "590px"
        };

        $c.win.openPopup("/bizspt/ULDSTF30305.gfm", options); // 대상 팝업은 반환값 없음(콜백 불요)
        scwin.clickId = "";
        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30304.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description 시작일 달력 아이콘 클릭 이벤트 — 달력 팝업을 호출한다.
 * @returns {void}
 * @hidden N
 * @example scwin.icn_SCal_onclick();
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description 종료일 달력 아이콘 클릭 이벤트 — 달력 팝업을 호출한다.
 * @returns {void}
 * @hidden N
 * @example scwin.icn_ECal_onclick();
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 조회 버튼 클릭 이벤트 — 검색조건으로 IR자료실 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Search_onclick();
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_irDataRoomList_OnFail
 * @description IR자료실 목록 데이터셋 처리 실패 콜백 — 오류 내용을 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_irDataRoomList_OnFail();
 */
scwin.dts_irDataRoomList_OnFail = function() {
    try {
        $c.win.alert(dts_irDataRoomList);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.dts_irDataRoomList_OnFail" });
    }
};

/**
 * @method
 * @name dts_irDataRoomList_OnLoadError
 * @description IR자료실 목록 데이터셋 로드 오류 콜백 — 오류 내용을 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_irDataRoomList_OnLoadError();
 */
scwin.dts_irDataRoomList_OnLoadError = function() {
    try {
        $c.win.alert(dts_irDataRoomList);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.dts_irDataRoomList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_irDataRoomList_OnLoadCompleted
 * @description IR자료실 목록 데이터셋 로드 완료 콜백 — 총 건수를 표시하고 0건이면 목록을 비운다.
 * @param {Number} rowcount 조회된 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.dts_irDataRoomList_OnLoadCompleted(10);
 */
scwin.dts_irDataRoomList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_irDataRoomList.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.dts_irDataRoomList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 그리드 더블클릭 이벤트 — 제목 컬럼이면 IR자료실 수정 팝업을 열어 저장 후 목록을 재조회하고, 회사명 컬럼이면 법인정보 팝업을 호출한다.
 * @param {Number} row 더블클릭한 행 인덱스
 * @param {String} colid 더블클릭한 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 * @example await scwin.grd_Grid_OnDblClick(0, "TITLE");
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.gIsurCd = dts_irDataRoomList.getCellData(row, "ISUR_CD");

        if (colid === 'TITLE') {
            scwin.setId(row);
            // 변경        await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30305.gfm", "IR자료실 수정", 200, 100, 725, 590, "window");
            const data = {};
            const options = {
                "id": "IR_UPDATE",
                "width": "720px",
                "height": "590px",
                "popupName": "IR자료실 수정",
                frameModal: "top",
                "modal": true
            };

            await $c.win.openPopup("/ui/dis/bizspt/ULDSTF30305.xml", options, data);
            scwin.listSync();
        } else if (colid === "COM_NM") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30304.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description 회사 자동완성 그리드 키 입력 이벤트 — Enter(13) 입력 시 선택 회사를 확정한다.
 * @param {String} kcode 입력된 키 코드
 * @returns {void}
 * @hidden N
 * @example scwin.Grd_com_isur_OnKeyPress('13');
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description 회사 자동완성 그리드 더블클릭 이벤트 — 선택 회사를 확정한다.
 * @param {Number} row 더블클릭한 행 인덱스
 * @param {String} colid 더블클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.Grd_com_isur_OnDblClick(0, "COM_ABBRV");
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description 회사 자동완성 그리드 클릭 이벤트 — 그리드 표시 상태를 유지한다.
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.Grd_com_isur_OnClick(0, "COM_ABBRV");
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description 회사 자동완성 그리드 포커스 진입 이벤트 — 포커스 플래그를 세팅한다.
 * @returns {void}
 * @hidden N
 * @example scwin.Grd_com_isur_OnSetFocus();
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description 회사 자동완성 그리드 포커스 이탈 이벤트 — 포커스 플래그를 해제하고 그리드를 숨긴다.
 * @returns {void}
 * @hidden N
 * @example scwin.Grd_com_isur_OnKillFocus();
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description 회사코드 입력 blur 이벤트 — 자동완성 그리드를 숨기고, 회사코드가 비어 있으면 회사명을 초기화한다.
 * @returns {void}
 * @hidden N
 * @example scwin.txb_isur_cd_onblur();
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description 회사코드 입력 포커스 이벤트 — 자동완성 그리드를 숨긴다.
 * @returns {void}
 * @hidden N
 * @example scwin.txb_isur_cd_onfocus();
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description 회사코드 입력 keyup 이벤트 — 아래화살표면 자동완성 그리드로 포커스를 이동하고, 그 외에는 회사명 자동완성 검색을 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txb_isur_cd_onkeyup(e);
 */
scwin.txb_isur_cd_onkeyup = function (e) {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (Number(e.keyCode) === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(e.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description 회사 데이터셋 필터 콜백 — 검색어(skw)로 회사명/구회사명을 필터링한다.
 * @param {Number} row 필터 대상 행 인덱스
 * @returns {Boolean} 필터 조건에 해당하면 true, 아니면 false
 * @hidden N
 * @example scwin.MxDataSet_com_isur_OnFilter(0);
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description 시장구분 라디오 변경 이벤트(현재 처리 없음).
 * @returns {void}
 * @hidden N
 * @example scwin.rdo_MKT_ID_onselchange();
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀 버튼 클릭 이벤트 — 그리드 목록을 엑셀 파일로 다운로드한다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Excel_onclick();
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 화면에 호출값보여줄때    $c.stf.doLogSave(scwin.vScrenID, $c.stf.info("SCREN_PROCS_TP_CD_07"), '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "IR자료실", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30304.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_oncelldblclick
 * @description 그리드 셀 더블클릭 이벤트 — 기존 이벤트 함수(grd_Grid_OnDblClick)로 위임한다.
 * @param {Number} rowIndex 더블클릭한 행 인덱스
 * @param {Number} columnIndex 더블클릭한 컬럼 인덱스
 * @param {String} columnId 더블클릭한 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 * @example await scwin.grd_Grid_oncelldblclick(0, 2, "TITLE");
 */
scwin.grd_Grid_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.grd_Grid_OnDblClick(rowIndex, columnId) ;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30304.grd_Grid_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name listSync
 * @description 조회기간 체크 후 검색조건으로 IR자료실 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = function() {
    if (scwin.dateCheck() === false) {
        return;
    }
    const com_cd = txb_isur_cd.getValue();
    /*
    const sbmOptions = {
        id : "sbm_dts_irDataRoomList",
        action : "/IRMgt.do",
        ref : "",
        target : "dts_irDataRoomList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_irDataRoomList_OnLoadCompleted(dts_irDataRoomList.getRowCount()); // 구 콜백 연결


    $c.cm.ShowWin(grd_Grid);
    */
    const _irmgtData = [
            "기업설명회(IR) 개최","레인보우로보틱스",1,"2026-05-12 11:11","국문","1800","27781","277810","","","","","","Y","Y","2026-05-12","승인"
            ,"기업설명회(IR) 개최","빛샘전자",0,"2026-05-12 11:05","국문","1799","07295","072950","","","","","","Y","Y","2026-05-05","승인"
            ,"TEST","프로티나",1,"2026-05-12 10:46","국문","1798","46853","468530","","","","","","Y","Y","2026-05-12","승인"
    ];

    dts_irDataRoomList.setData(_irmgtData);
};

/**
 * @method
 * @name setId
 * @description 선택 행의 자료실ID(RESOROOM_ID)와 제출여부(SUBMIT_YN)를 화면 변수에 세팅한다.
 * @param {Number} obj 선택한 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.setId(0);
 */
scwin.setId = function(obj) {
    if (scwin.clickId !== "input") {
        scwin.clickId = dts_irDataRoomList.getCellData(obj, "RESOROOM_ID");
        scwin.clickSubmitYn = dts_irDataRoomList.getCellData(obj, "SUBMIT_YN");
    }
};

/**
 * @method
 * @name getId
 * @description 현재 선택된 자료실ID(clickId)를 반환한다(팝업 화면에서 참조).
 * @returns {String} 선택된 자료실ID
 * @hidden N
 * @example const id = scwin.getId();
 */
scwin.getId = function() {
    return scwin.clickId;
};

/**
 * @method
 * @name dateCheck
 * @description 조회기간 체크 — 시작일이 종료일보다 크면 경고 후 당일로 재설정하고 false를 반환한다.
 * @returns {Boolean} 기간 오류 시 false(정상이면 반환값 없음)
 * @hidden N
 * @example if (scwin.dateCheck() === false) return;
 */
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.utils.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.utils.cGetToday("yyyymmdd"));
        return false;
    }
};

/**
 * @method
 * @name getChkValue
 * @description 체크박스 체크 여부에 따라 체크 시 value, 미체크 시 "0"을 반환한다.
 * @param {Object} obj 체크박스 객체
 * @returns {String} 체크 시 obj.value, 미체크 시 "0"
 * @hidden N
 * @example const v = scwin.getChkValue(obj);
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.value;
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description 체크박스의 체크 상태를 설정한다.
 * @param {Object} obj 체크박스 객체
 * @param {Boolean} booleanVal 설정할 체크 상태
 * @returns {void}
 * @hidden N
 * @example scwin.setChkValue(obj, true);
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.checked = booleanVal;
};

/**
 * @method
 * @name gform_onload
 * @description 화면 초기화 — 조회기간 기본값(한달전~오늘)과 시장구분을 세팅하고, 시장 사용자면 시장구분 영역을 숨긴 뒤 목록 조회와 회사코드 자동완성을 초기화한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
    // 주석합니다.    $c.libRoundPanel.PanelToGroupBox(panel_1);
    const vCurDate = $c.utils.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.utils.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_EDate.setValue(vCurDate);
    rdo_MKT_ID.setValue($c.session.info("js_market"));
    if ($c.session.info("js_market") === '1' || $c.session.info("js_market") === '2' || $c.session.info("js_market") === '6') {
        panel_mkt.hide();
    }
    scwin.listSync();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
